#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;
vector<long long> factorials, invFactorials;

void initializeFactorials() {
    factorials.resize(200001);
    invFactorials.resize(200001);
    factorials[0] = 1;
    invFactorials[0] = 1;
    for (int i = 1; i <= 200000; i++) {
        factorials[i] = (factorials[i - 1] * i) % MOD;
        invFactorials[i] = powMod(factorials[i], MOD - 2, MOD);
    }
}

long long ncr(int n, int r) {
    return (((factorials[n] * invFactorials[r]) % MOD) * invFactorials[n - r]) % MOD;
}

long long powMod(long long base, long long exp, long long mod) {
    long long res = 1;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    initializeFactorials();

    long long n, k;
    cin >> n >> k;

    if (k > n) {
        cout << 0 << "\n";
        return 0;
    }

    long long remaining = n - k;
    long long total = 0;

    for (int i = 0; i <= remaining; i++) {
        long long term = (ncr((int)remaining, i) * powMod(remaining - i, n, MOD)) % MOD;
        if (i % 2 == 0)
            total += term;
        else
            total -= term;
        total = (total + MOD) % MOD;
    }

    long long answer = (total * ncr((int)n, (int)remaining)) % MOD;

    if (remaining == 0)
        cout << answer << "\n";
    else
        cout << (2 * answer) % MOD << "\n";

    return 0;
}
